import { expect, expectTypeOf, assertType } from "./test/expect-shim.mjs";
import { throttle } from "./src/function/throttle.js";
import { delay } from "./src/promise/delay.js";
{
{
{
const throttleMs = 50;
        let capturedMsg;
        const obj = {
            msg: 'hello world',
            logWithThrottle: throttle(function () {
                capturedMsg = this?.msg;
            }, throttleMs),
        };
        obj.logWithThrottle();
        expect(capturedMsg).toBe('hello world');
        capturedMsg = undefined;
        obj.logWithThrottle();
        obj.logWithThrottle();
        await delay(throttleMs + 1);
        expect(capturedMsg).toBe('hello world');
}
}
}

